export async function addBillingRecord(data: InsertBillingHistory) {
  const db = await getDb();
  if (!db) throw new Error("Database not available");

  await db.insert(billingHistory).values(data);
}

export async function getBillingHistory(userId: number, limit: number = 10) {
  const db = await getDb();
  if (!db) return [];

  return db.select()
    .from(billingHistory)
    .where(eq(billingHistory.userId, userId))
    .orderBy(desc(billingHistory.createdAt))
    .limit(limit);
}

