// ============ Rate Limiting Functions ============

export async function checkRateLimit(userId: number, plan: string): Promise<{
  allowed: boolean;
  remaining: number;
  resetAt: Date;
}> {
  const planLimits: Record<string, { calls: number; rate: number }> = {
    free: { calls: 2000, rate: 10 },
    builder: { calls: 25000, rate: 60 },
    startup: { calls: 150000, rate: 300 },
    scale: { calls: 500000, rate: 1000 },
    business: { calls: 2000000, rate: 5000 },
    enterprise: { calls: Infinity, rate: 10000 },
    enterprise_plus: { calls: Infinity, rate: 50000 },
  };

  const limits = planLimits[plan] || planLimits.free;
  const key = `rate:${userId}`;
  const now = new Date();
  const _windowStart = new Date(now.getTime() - 60000); // 1 minute window (reserved for windowed rate-limit)

  // Get or create rate limit record
  const { data: existing } = await supabase
    .from('rate_limits')
    .select('*')
    .eq('key', key)
    .gte('expires_at', now.toISOString())
    .single();

  if (existing) {
    const allowed = existing.count < limits.rate;
    if (allowed) {
      await supabase
        .from('rate_limits')
        .update({ count: existing.count + 1 })
        .eq('id', existing.id);
    }
    return {
      allowed,
      remaining: Math.max(0, limits.rate - existing.count - 1),
      resetAt: new Date(existing.expires_at),
    };
  }

  // Create new rate limit window
  const expiresAt = new Date(now.getTime() + 60000);
  await supabase
    .from('rate_limits')
    .insert({
      key,
      count: 1,
      window_start: now.toISOString(),
      expires_at: expiresAt.toISOString(),
    });

  return {
    allowed: true,
    remaining: limits.rate - 1,
    resetAt: expiresAt,
  };
}

