/**
 * Supabase Database Layer for Gravito
 * 
 * This module provides database operations using Supabase's JavaScript client.
 * It mirrors the functionality in db.ts but uses Supabase PostgreSQL instead of MySQL.
 * 
 * To use Supabase as the primary database:
 * 1. Create tables in Supabase Dashboard (SQL Editor)
 * 2. Import functions from this file instead of db.ts
 * 3. Update routers.ts to use supabase-db functions
 */

import { supabase } from './supabase';
import { createHash, randomBytes } from 'crypto';
import { dbLog } from './_core/logger';
import { ENV } from './_core/env';

// ============ Types ============

export interface User {
  id: number;
  open_id: string;
  name: string | null;
  email: string | null;
  login_method: string | null;
  password_hash: string | null;
  role: 'admin' | 'user';
  last_signed_in: string | null;
  created_at: string;
  updated_at: string;
}

export interface ApiKey {
  id: number;
  user_id: number;
  key_hash: string;
  key_prefix: string;
  name: string;
  is_active: boolean;
  last_used_at: string | null;
  created_at: string;
}

/**
 * The columns `getApiKeysByUserId` actually selects — the secret-bearing
 * `key_hash` and the redundant `user_id` are deliberately not read back.
 * Every listed column is always present, so this is a Pick, not a Partial.
 */
export type ApiKeySummary = Pick<
  ApiKey,
  'id' | 'key_prefix' | 'name' | 'is_active' | 'last_used_at' | 'created_at'
>;

export interface Subscription {
  id: number;
  user_id: number;
  plan: string;
  stripe_customer_id: string | null;
  stripe_subscription_id: string | null;
  status: string;
  current_period_start: string | null;
  current_period_end: string | null;
  cancel_at_period_end: boolean;
  created_at: string;
  updated_at: string;
}

export interface ApiUsage {
  id: number;
  user_id: number;
  api_key_id: number | null;
  endpoint: string;
  call_count: number;
  date: string;
  created_at: string;
}

export interface BillingHistory {
  id: number;
  user_id: number;
  stripe_invoice_id: string | null;
  stripe_payment_intent_id: string | null;
  amount: number;
  currency: string;
  status: string;
  description: string | null;
  created_at: string;
}

export interface RateLimit {
  id: number;
  key: string;
  count: number;
  window_start: string;
  expires_at: string;
}

export interface EmotionalHistory {
  id: number;
  user_id: number;
  external_user_id: string | null;
  emotion: string;
  valence: number;
  arousal: number;
  escalation_risk: 'low' | 'medium' | 'high';
  context: string | null;
  conversation_id: string | null;
  created_at: string;
}

export interface EmotionalPattern {
  id: number;
  user_id: number;
  external_user_id: string | null;
  pattern_type: 'recurring_frustration' | 'escalation_prone' | 'positive_engagement' | 'time_sensitive' | 'topic_triggered';
  description: string;
  triggers: string | null;
  frequency: number;
  last_occurrence: string;
  recommended_approach: string | null;
  created_at: string;
  updated_at: string;
}

export interface Lead {
  id: number;
  email: string;
  company_name: string | null;
  company_size: string | null;
  industry: string | null;
  source_page: string | null;
  utm_source: string | null;
  utm_medium: string | null;
  utm_campaign: string | null;
  escalation_risk: number | null;
  churn_probability: number | null;
  value_at_risk: number | null;
  lead_score: number;
  lead_tier: 'cold' | 'warm' | 'hot' | 'qualified';
  status: string;
  notes: string | null;
  created_at: string;
  updated_at: string;
}

// ============ User Functions ============

export async function upsertUser(userData: {
  openId: string;
  name?: string | null;
  email?: string | null;
  loginMethod?: string | null;
  passwordHash?: string | null;
  role?: 'admin' | 'user';
  lastSignedIn?: Date;
}): Promise<User | null> {
  // Build the upsert payload from ONLY the fields the caller actually provided.
  // PostgREST upsert (resolution=merge-duplicates) updates exactly the columns
  // present in the payload on conflict and leaves omitted columns UNCHANGED, so
  // partial updates (e.g. the per-request `last_signed_in` touch from
  // authenticateRequest, which passes only openId + lastSignedIn) must NOT carry
  // name/email/role — otherwise an existing user's profile and, critically, an
  // admin's `role` would be clobbered to defaults on every login/request.
  //
  // `role` is only written when explicitly provided, else self-healed to 'admin'
  // for the owner openId; otherwise it is omitted so the existing value is
  // preserved on conflict (and falls back to the column default 'user' on a true
  // insert). Mirrors the role-preservation + owner self-heal in server/db.ts.
  const payload: Record<string, unknown> = {
    open_id: userData.openId,
    last_signed_in: userData.lastSignedIn?.toISOString() ?? new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  if (userData.name !== undefined) payload.name = userData.name ?? null;
  if (userData.email !== undefined) payload.email = userData.email ?? null;
  if (userData.loginMethod !== undefined) payload.login_method = userData.loginMethod ?? null;
  if (userData.passwordHash !== undefined) payload.password_hash = userData.passwordHash ?? null;
  if (userData.role !== undefined) {
    payload.role = userData.role;
  } else if (userData.openId && userData.openId === ENV.ownerOpenId) {
    payload.role = 'admin';
  }

  const { data, error } = await supabase
    .from('users')
    .upsert(payload, {
      onConflict: 'open_id',
    })
    .select()
    .single();

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error upserting user');
    return null;
  }
  return data;
}

export async function getUserByOpenId(openId: string): Promise<User | null> {
  const { data, error } = await supabase
    .from('users')
    .select('*')
    .eq('open_id', openId)
    .single();

  if (error) {
    if (error.code !== 'PGRST116') { // Not found is expected
      dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting user by openId');
    }
    return null;
  }
  return data;
}

export async function getUserById(id: number): Promise<User | null> {
  const { data, error } = await supabase
    .from('users')
    .select('*')
    .eq('id', id)
    .single();

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting user by id');
    return null;
  }
  return data;
}

export async function getUserByEmail(email: string): Promise<User | null> {
  const { data, error } = await supabase
    .from('users')
    .select('*')
    .eq('email', email)
    .single();

  if (error) {
    if (error.code !== 'PGRST116') {
      dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting user by email');
    }
    return null;
  }
  return data;
}

// ============ API Key Functions ============

function hashApiKey(key: string): string {
  return createHash('sha256').update(key).digest('hex');
}

export function generateApiKey(): { key: string; hash: string; prefix: string } {
  const key = `grav_${randomBytes(32).toString('hex')}`;
  const hash = hashApiKey(key);
  // Prod `api_keys.key_prefix` is varchar(12) NOT NULL — a 16-char prefix
  // overflows it (Postgres 22001) and silently fails key creation/regeneration.
  const prefix = key.substring(0, 12);
  return { key, hash, prefix };
}

export async function createApiKey(userId: number, name?: string): Promise<{ key: string; prefix: string } | null> {
  const { key, hash, prefix } = generateApiKey();

  const { error } = await supabase
    .from('api_keys')
    .insert({
      user_id: userId,
      key_hash: hash,
      key_prefix: prefix,
      name: name || 'Default Key',
      is_active: true,
    });

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error creating API key');
    return null;
  }
  return { key, prefix };
}

export async function getApiKeysByUserId(userId: number): Promise<Partial<ApiKey>[]> {
  const { data, error } = await supabase
    .from('api_keys')
    .select('id, key_prefix, name, is_active, last_used_at, created_at')
    .eq('user_id', userId);

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting API keys');
    return [];
  }
  return data || [];
}

export async function validateApiKey(key: string): Promise<ApiKey | null> {
  const hash = hashApiKey(key);

  const { data, error } = await supabase
    .from('api_keys')
    .select('*')
    .eq('key_hash', hash)
    .eq('is_active', true)
    .single();

  if (error) {
    return null;
  }

  // Update last used
  await supabase
    .from('api_keys')
    .update({ last_used_at: new Date().toISOString() })
    .eq('id', data.id);

  return data;
}

export async function deleteApiKey(userId: number, keyId: number): Promise<boolean> {
  const { error } = await supabase
    .from('api_keys')
    .delete()
    .eq('id', keyId)
    .eq('user_id', userId);

  return !error;
}

export async function regenerateApiKey(userId: number, keyId: number): Promise<{ key: string; prefix: string } | null> {
  const { key, hash, prefix } = generateApiKey();

  const { error } = await supabase
    .from('api_keys')
    .update({ key_hash: hash, key_prefix: prefix })
    .eq('id', keyId)
    .eq('user_id', userId);

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error regenerating API key');
    return null;
  }
  return { key, prefix };
}

// ============ Subscription Functions ============

export async function getSubscriptionByUserId(userId: number): Promise<Subscription | null> {
