}

export async function createOrUpdateSubscription(subData: {
  userId: number;
  plan: string;
  stripeCustomerId?: string | null;
  stripeSubscriptionId?: string | null;
  status?: string;
  currentPeriodStart?: Date | null;
  currentPeriodEnd?: Date | null;
  cancelAtPeriodEnd?: boolean;
}): Promise<boolean> {
  const { error } = await supabase
    .from('subscriptions')
    .upsert({
      userId: subData.userId,
      plan: subData.plan,
      stripeCustomerId: subData.stripeCustomerId ?? null,
      stripeSubscriptionId: subData.stripeSubscriptionId ?? null,
      status: subData.status ?? 'active',
      currentPeriodStart: subData.currentPeriodStart?.toISOString() ?? null,
      currentPeriodEnd: subData.currentPeriodEnd?.toISOString() ?? null,
      cancelAtPeriodEnd: subData.cancelAtPeriodEnd ?? false,
      updatedAt: new Date().toISOString(),
    }, {
      onConflict: 'userId',
    });

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error creating/updating subscription');
    return false;
  }
  return true;
}

// ============ Usage Functions ============

export async function recordApiUsage(userId: number, apiKeyId: number | null, endpoint: string): Promise<void> {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const todayStr = today.toISOString().split('T')[0];

  // Try to find existing record for today
  const { data: existing } = await supabase
    .from('api_usage')
    .select('id, callCount')
    .eq('userId', userId)
    .eq('endpoint', endpoint)
    .eq('date', todayStr)
    .single();

  if (existing) {
    // Increment existing record
    await supabase
      .from('api_usage')
      .update({ callCount: existing.callCount + 1 })
      .eq('id', existing.id);
  } else {
    // Create new record
    await supabase
      .from('api_usage')
      .insert({
        userId: userId,
        apiKeyId: apiKeyId,
        endpoint,
        callCount: 1,
        date: todayStr,
      });
  }
}

export async function getUsageByUserId(userId: number, days: number = 30): Promise<ApiUsage[]> {
  const startDate = new Date();
  startDate.setDate(startDate.getDate() - days);

  const { data, error } = await supabase
    .from('api_usage')
    .select('*')
    .eq('userId', userId)
    .gte('date', startDate.toISOString().split('T')[0])
    .order('date', { ascending: false });

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting usage');
    return [];
  }
  return data || [];
}

export async function getTotalUsageThisMonth(userId: number): Promise<number> {
  const startOfMonth = new Date();
  startOfMonth.setDate(1);
  startOfMonth.setHours(0, 0, 0, 0);

  const { data, error } = await supabase
    .from('api_usage')
    .select('callCount')
    .eq('userId', userId)
    .gte('date', startOfMonth.toISOString().split('T')[0]);

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting total usage');
    return 0;
  }

  return data?.reduce((sum, row) => sum + (row.callCount || 0), 0) || 0;
}

// ============ Billing Functions ============

export async function addBillingRecord(billingData: {
  userId: number;
  stripeInvoiceId?: string | null;
  stripePaymentIntentId?: string | null;
  amount: number;
  currency?: string;
  status: string;
  description?: string | null;
}): Promise<boolean> {
  const { error } = await supabase
    .from('billing_history')
    .insert({
      userId: billingData.userId,
      stripeInvoiceId: billingData.stripeInvoiceId ?? null,
      // NOTE: prod `billing_history` has NO payment-intent column (verified against
      // drizzle/schema.ts + drizzle/migrations/0000_clean_whistler.sql — only the
      // `fix_orders` table carries `stripePaymentIntentId`). Inserting it would 400
      // the whole row, so the caller-supplied stripePaymentIntentId is intentionally
      // NOT written here. The param is kept on the signature for caller compatibility.
      amount: billingData.amount,
      currency: billingData.currency ?? 'usd',
      status: billingData.status,
      description: billingData.description ?? null,
    });

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error adding billing record');
    return false;
  }
  return true;
}

export async function getBillingHistory(userId: number, limit: number = 10): Promise<BillingHistory[]> {
