export async function updateLead(id: number, updates: {
  status?: string;
  notes?: string;
  escalationRisk?: number | null;
  churnProbability?: number | null;
  valueAtRisk?: number | null;
  scanConversation?: string | null;
  lastContactedAt?: Date;
  ownerNotified?: boolean;
  crisisReportSent?: boolean;
  pilotAgentTriggered?: boolean;
}): Promise<boolean> {
  const updateData: Record<string, unknown> = {
    updated_at: new Date().toISOString(),
  };

  if (updates.status !== undefined) updateData.status = updates.status;
  if (updates.notes !== undefined) updateData.notes = updates.notes;
  if (updates.escalationRisk !== undefined) updateData.escalation_risk = updates.escalationRisk;
  if (updates.churnProbability !== undefined) updateData.churn_probability = updates.churnProbability;
  if (updates.valueAtRisk !== undefined) updateData.value_at_risk = updates.valueAtRisk;
  if (updates.scanConversation !== undefined) updateData.scan_conversation = updates.scanConversation;
  if (updates.lastContactedAt !== undefined) updateData.last_contacted_at = updates.lastContactedAt.toISOString();
  if (updates.ownerNotified !== undefined) updateData.owner_notified = updates.ownerNotified;
  if (updates.crisisReportSent !== undefined) updateData.crisis_report_sent = updates.crisisReportSent;
  if (updates.pilotAgentTriggered !== undefined) updateData.pilot_agent_triggered = updates.pilotAgentTriggered;

  // Recalculate lead score if risk metrics changed
  if (updates.escalationRisk !== undefined || updates.churnProbability !== undefined || updates.valueAtRisk !== undefined) {
    const lead = await getLeadById(id);
    if (lead) {
      const { score, tier } = calculateLeadScore({
        escalationRisk: updates.escalationRisk ?? lead.escalation_risk ?? undefined,
        churnProbability: updates.churnProbability ?? lead.churn_probability ?? undefined,
        valueAtRisk: updates.valueAtRisk ?? lead.value_at_risk ?? undefined,
      });
      updateData.lead_score = score;
      updateData.lead_tier = tier;
    }
  }

  const { error } = await supabase
    .from('leads')
    .update(updateData)
    .eq('id', id);

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error updating lead');
    return false;
  }
  return true;
}

