// ============ Lead Functions ============

function convertLeadToCamel(lead: supabaseDb.Lead): Lead {
  return {
    id: lead.id,
    email: lead.email,
    company: lead.company_name,
    companySize: lead.company_size,
    industry: lead.industry,
    sourcePage: lead.source_page,
    utmSource: lead.utm_source,
    utmMedium: lead.utm_medium,
    utmCampaign: lead.utm_campaign,
    utmContent: null, // Not in Supabase schema
    utmTerm: null, // Not in Supabase schema
    escalationRisk: lead.escalation_risk,
    churnProbability: lead.churn_probability,
    valueAtRisk: lead.value_at_risk,
    scanConversation: null, // Not in Supabase schema yet
    leadScore: lead.lead_score,
    leadTier: lead.lead_tier,
    status: lead.status,
    notes: lead.notes,
    ownerNotified: false, // Not in Supabase schema yet
    crisisReportSent: false, // Not in Supabase schema yet
    pilotAgentTriggered: false, // Not in Supabase schema yet
    lastContactedAt: null, // Not in Supabase schema yet
    createdAt: lead.created_at,
    updatedAt: lead.updated_at,
  };
}

export async function createLead(leadData: {
  email: string;
  company?: string | null;
  sourcePage?: string | null;
  utmSource?: string | null;
  utmMedium?: string | null;
  utmCampaign?: string | null;
  utmContent?: string | null;
  utmTerm?: string | null;
  escalationRisk?: number | null;
  churnProbability?: number | null;
  valueAtRisk?: number | null;
  scanConversation?: string | null;
}): Promise<Lead | null> {
  const result = await supabaseDb.createLead({
    email: leadData.email,
    companyName: leadData.company,
    sourcePage: leadData.sourcePage,
    utmSource: leadData.utmSource,
    utmMedium: leadData.utmMedium,
    utmCampaign: leadData.utmCampaign,
    escalationRisk: leadData.escalationRisk,
    churnProbability: leadData.churnProbability,
    valueAtRisk: leadData.valueAtRisk,
  });

  if (!result) return null;
  return convertLeadToCamel(result);
}

